type View = "overview" | "subjects" | "topics" | "tasks" | "calendar" | "sessions" | "topic-detail" | "task-detail" | "session-detail";
type Modal = "subject" | "topic" | "task" | "session" | null;
type EditTarget = { kind: "subject"; value: Subject } | { kind: "topic"; value: Topic } | { kind: "task"; value: Task };
type DeleteTarget = { kind: "subject" | "topic" | "task" | "session"; id: string; name: string };
type Accent = string;
const GUIDED_TOUR_STEPS = 11;
const difficultyKey = (value: string | null) => ({Easy:"Łatwy",Medium:"Średni",Hard:"Trudny",easy:"Łatwy",medium:"Średni",hard:"Trudny",Łatwe:"Łatwy",Średnie:"Średni",Trudne:"Trudny"} as Record<string,string>)[value??""] ?? value;
const difficultyLabel = (value: string | null) => value ? t(({Łatwy:"Easy",Średni:"Medium",Trudny:"Hard"} as Record<string,string>)[difficultyKey(value)??""] ?? value) : t("No level");

const fmtDate = (value: string | null) => value ? new Intl.DateTimeFormat(locale(), { day: "numeric", month: "short" }).format(new Date(/^\d{4}-\d{2}-\d{2}$/.test(value)?`${value}T12:00`:value)) : t("No deadline");
const initials = (name: string) => name.slice(0, 2).toUpperCase();
const localDay = (date: Date) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
function studyStreak(sessions: Session[]) { const days=new Set(sessions.map(s=>localDay(new Date(s.started_at)))); let cursor=new Date(); if(!days.has(localDay(cursor))) cursor.setDate(cursor.getDate()-1); let count=0; while(days.has(localDay(cursor))){count++;cursor.setDate(cursor.getDate()-1)} return count; }

function Brand({onHome}:{onHome?:()=>void}) {
  return <button type="button" className="brand" onClick={onHome}><span className="brand-mark"><Sparkles size={18} /></span><span>studyflow<span className="dot">.</span></span></button>;
}

function AccentPicker({value,change,className=""}:{value:Accent;change:(accent:Accent)=>void;className?:string}) {
  const accents:{id:Accent;label:string;color:string}[]=[{id:"lime",label:t("Lime"),color:"#c8f05a"},{id:"violet",label:t("Violet"),color:"#a78bfa"},{id:"pink",label:t("Pink"),color:"#f472b6"},{id:"blue",label:t("Blue"),color:"#60a5fa"},{id:"graphite",label:t("Graphite"),color:"#94a3b8"}];
  const [open,setOpen]=useState(false);const selected=accents.find(accent=>accent.id===value);const selectedColor=selected?.color??(value.startsWith("#")?value:"#c8f05a");
  function selectAccent(accent:Accent){document.documentElement.classList.add("accent-changing");change(accent);window.setTimeout(()=>document.documentElement.classList.remove("accent-changing"),520);window.setTimeout(()=>setOpen(false),160)}
  return <section className={`accent-picker ${open?"open":""} ${className}`}><button type="button" className="accent-picker-trigger" onClick={()=>setOpen(current=>!current)} aria-expanded={open}><i style={{"--swatch":selectedColor} as React.CSSProperties}/><span>{t("Theme color")}</span><ChevronDown/></button><div className="accent-picker-options" aria-hidden={!open}>{accents.map(accent=><button type="button" key={accent.id} className={value===accent.id?"active":""} style={{"--swatch":accent.color} as React.CSSProperties} onClick={()=>selectAccent(accent.id)} title={accent.label} aria-label={t("Theme {0}", accent.label)} tabIndex={open?0:-1}><i/>{value===accent.id&&<Check/>}</button>)}<label className={!selected?"custom-accent active":"custom-accent"} title={t("Custom color")}><input type="color" value={selectedColor} onChange={event=>selectAccent(event.target.value)} tabIndex={open?0:-1}/><span style={{"--swatch":selectedColor} as React.CSSProperties}/><Sparkles/></label></div></section>
}

function SubjectColorField({initial}:{initial:string}){
  const [color,setColor]=useState(initial);
  return <label>{t("Subject color")}<div className="subject-color-field"><input type="color" name="color" value={color} onChange={event=>setColor(event.target.value)} aria-label={t("Choose a subject color")}/><span className="subject-color-preview" style={{background:color}}/><strong>{color.toUpperCase()}</strong></div><small className="field-hint">{t("The selected color will appear on the subject, topics, and in the calendar.")}</small></label>;
}

type SelectOption = { value: string; label: string };
function SelectField({ name, options, defaultValue, required, onChange }: { name: string; options: SelectOption[]; defaultValue?: string; required?: boolean; onChange?: (value:string)=>void }) {
  const initial = defaultValue ?? options[0]?.value ?? ""; const [value, setValue] = useState(initial); const [open, setOpen] = useState(false);
  useEffect(()=>{if(!open)return;const escape=(event:KeyboardEvent)=>{if(event.key==="Escape"){event.stopImmediatePropagation();setOpen(false)}};document.addEventListener("keydown",escape,true);return()=>document.removeEventListener("keydown",escape,true)},[open]);
  const selected = options.find(option => option.value === value);
  return <div className={open ? "custom-select open" : "custom-select"}><input type="hidden" name={name} value={value} required={required}/><button type="button" className="select-trigger" onClick={()=>setOpen(!open)}><span>{selected?.label ?? t("Select...")}</span><ChevronDown /></button>{open&&<div className="select-options">{options.map(option=><button type="button" className={option.value===value?"selected":""} key={option.value} onClick={()=>{setValue(option.value);onChange?.(option.value);setOpen(false);}}><span>{option.label}</span>{option.value===value&&<Check />}</button>)}</div>}</div>;
}


function Auth({ onReady, language, onLanguageChange }: { onReady: (newAccount:boolean) => void; language: Language; onLanguageChange: (language:Language) => void }) {
  const [register, setRegister] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [languageChosen, setLanguageChosen] = useState(false);
  const [languageOpen, setLanguageOpen] = useState(false);
  const languageMenuRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!languageOpen) return;
    const closeOutside = (event: PointerEvent) => {
      if (!languageMenuRef.current?.contains(event.target as Node)) setLanguageOpen(false);
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setLanguageOpen(false);
        languageMenuRef.current?.querySelector<HTMLButtonElement>(".auth-language-trigger")?.focus();
      }
    };
    document.addEventListener("pointerdown", closeOutside);
    document.addEventListener("keydown", closeOnEscape);
    return () => {
      document.removeEventListener("pointerdown", closeOutside);
      document.removeEventListener("keydown", closeOnEscape);
    };
  }, [languageOpen]);
  function chooseLanguage(next: Language) {
    setLanguage(next, false);
    onLanguageChange(next);
    setLanguageChosen(true);
    setLanguageOpen(false);
    setError("");
  }
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setError("");
    const data = new FormData(e.currentTarget);
    const username = String(data.get("username")); const password = String(data.get("password"));
    if(register&&password!==String(data.get("confirm_password"))){setError(t("Passwords must match."));return}
    setBusy(true);
    try {
      if (register) await api.register(username, String(data.get("email")), password);
      const result = await api.login(username, password);
      setToken(result.access_token);
      if (languageChosen) {
        try { await api.updateMe({ language }); }
        catch (error) { clearToken(); throw error; }
      }
      onReady(register);
    } catch (err) { setError(err instanceof Error ? err.message : t("Failed to log in.")); }
    finally { setBusy(false); }
  }
  return <main className="auth-page">
    <div className="orb orb-one" /><div className="orb orb-two" />
    <section className="auth-story">
      <Brand />
      <div><span className="eyebrow"><span /> {t("Your calm study system")}</span><h1>{t("Less chaos.")}<br /><em>{t("More progress.")}</em></h1><p>{t("Turn ambitious plans into small, concrete steps. StudyFlow helps you focus on what really matters.")}</p></div>
      <div className="quote"><div className="avatars"><span>MK</span><span>AN</span><span>+2k</span></div><p>{t("Join people who study smarter, not longer.")}</p></div>
    </section>
    <section className="auth-panel">
      <form className="auth-card" onSubmit={submit}>
        <div className="mobile-brand"><Brand /></div>
        <div className="auth-language" ref={languageMenuRef}>
          <button type="button" className="auth-language-trigger" aria-label={t("Language")} title={t("Language")} aria-haspopup="menu" aria-expanded={languageOpen} aria-controls="auth-language-menu" disabled={busy} onClick={() => setLanguageOpen(open => !open)}><Globe2 size={19} /></button>
          {languageOpen && <div className="auth-language-menu" id="auth-language-menu" role="menu" aria-label={t("Language")}>
            <button type="button" role="menuitemradio" lang="en" aria-checked={language === "en"} onClick={() => chooseLanguage("en")}><span>English</span>{language === "en" && <Check size={16} />}</button>
            <button type="button" role="menuitemradio" lang="pl" aria-checked={language === "pl"} onClick={() => chooseLanguage("pl")}><span>Polski</span>{language === "pl" && <Check size={16} />}</button>
          </div>}
        </div>
        <p className="kicker">{t("Welcome")}{register ? t("in StudyFlow") : t("again")}</p>
        <h2>{register ? t("Create account") : t("Ready for the next step?")}</h2>
        <p className="muted">{register ? t("Start organizing your studies today.") : t("Log in and continue your plan.")}</p>
        <label>{t("Username")}<input name="username" minLength={2} required placeholder={t("e.g. Matthew")} autoComplete="username" /></label>
        {register && <label>E-mail <span className="optional">{t("optional")}</span><input name="email" type="email" placeholder={t("you@email.pl")} autoComplete="email" /></label>}
        <label>{t("Password")}<input name="password" type="password" minLength={8} required placeholder={t("Minimum 8 characters")} autoComplete={register ? "new-password" : "current-password"} /></label>
        {register&&<label>{t("Confirm password")}<input name="confirm_password" type="password" minLength={8} required placeholder={t("Enter password again")} autoComplete="new-password" /></label>}
        {error && <p className="form-error styled-error"><X />{error}</p>}
        <button className="primary wide" disabled={busy}>{busy ? <span className="loader" /> : <>{register ? t("Sign up") : t("Enter app")}<ArrowRight size={18} /></>}</button>
        <p className="switch">{register ? t("Already have an account?") : t("Don't have an account yet?")} <button type="button" onClick={() => { setRegister(!register); setError(""); }}>{register ? t("Log in") : t("Create it")}</button></p>
      </form>
    </section>
  </main>;
}

function TaskSessionsOverview({sessions,openSession,addSession}:{sessions:Session[];openSession:(session:Session)=>void;addSession:()=>void}) {
  return <section className="panel task-sessions-overview"><div className="panel-head"><div><span className="kicker">{t("RELATED STUDY")}</span><h3>{t("Sessions of this task")}</h3></div><div className="related-session-actions"><strong>{sessions.length}</strong><button className="primary compact" onClick={addSession}><CirclePlus/>{t("Add session")}</button></div></div>{sessions.length?<div className="task-session-cards">{sessions.map(session=><button key={session.study_uid} onClick={()=>openSession(session)}><span className="session-date"><b>{new Date(session.started_at).getDate()}</b><small>{new Intl.DateTimeFormat(locale(),{month:"short"}).format(new Date(session.started_at))}</small></span><div><h4>{session.title}</h4><small>{session.duration_minutes??0} {t("min of study")}</small><p>{session.notes||t("No note")}</p></div><ChevronRight/></button>)}</div>:<Empty text={t("No study sessions have been assigned to this task yet.")}/>}</section>
}

function SessionDetailV2({session,subjects,topics,tasks,edit}:{session:Session;subjects:Subject[];topics:Topic[];tasks:Task[];edit:()=>void}) {const subject=subjects.find(item=>item.subject_uid===session.subject_uid);const topic=topics.find(item=>item.topic_uid===session.topic_uid);const task=tasks.find(item=>item.task_uid===session.task_uid);return <section className="detail-page view-enter"><div className="detail-hero session-detail-hero"><span className="kicker">{t("STUDY SESSION")}</span><h2>{session.title}</h2><p>{new Intl.DateTimeFormat(locale(),{dateStyle:"full",timeStyle:"short"}).format(new Date(session.started_at))}</p><div><button className="primary" onClick={edit}><Pencil/>{t("Edit session")}</button></div></div><div className="detail-grid"><article><Clock3/><small>{t("Study time")}</small><strong>{session.duration_minutes??0} {t("minutes")}</strong></article><article><BookOpen/><small>{t("Scope")}</small><strong>{subject?.name}{topic&&` · ${topic.name}`}{task&&` · ${task.title}`}</strong></article></div><article className="detail-notes"><span className="kicker">{t("SESSION NOTE")}</span><p>{session.notes||t("No note has been added to this session.")}</p></article></section>}

function SessionAiFields({initialTitle="",initialNotes=""}:{initialTitle?:string;initialNotes?:string}) {
  const [description,setDescription]=useState(""); const [title,setTitle]=useState(initialTitle); const [notes,setNotes]=useState(initialNotes); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  async function generate(){if(description.trim().length<3)return;setBusy(true);setError("");try{const result=await api.generateSessionNote(description.trim());setTitle(result.title);setNotes(result.notes)}catch(err){setError(err instanceof Error?err.message:t("Failed to prepare the note."))}finally{setBusy(false)}}
  return <div className="session-ai-fields"><label>{t("Session title")}<input name="title" required maxLength={160} value={title} onChange={event=>setTitle(event.target.value)} placeholder={t("e.g. Equation review")}/></label><label>{t("What did you do?")}<span className="optional">{t("a few words are enough")}</span><textarea value={description} onChange={event=>setDescription(event.target.value)} maxLength={1000} placeholder={t("e.g. I did 10 equation problems and reviewed formulas")}/></label><button type="button" className="session-ai-button" disabled={busy||description.trim().length<3} onClick={generate}>{busy?<span className="loader"/>:<Sparkles/>}{busy?t("AI is preparing the note…"):t("Create title and note with AI")}</button>{error&&<p className="form-error">{error}</p>}<label>{t("Session note")}<textarea name="notes" value={notes} onChange={event=>setNotes(event.target.value)} rows={6} placeholder={t("You can enter a note manually or generate one above.")}/></label></div>
}

function ModalForm({ type, subjects, topics, tasks, initialDeadline, initialTask, userId, close, done }: { type: Exclude<Modal, null>; subjects: Subject[]; topics: Topic[]; tasks: Task[]; initialDeadline?:string;initialTask?:Task|null;userId:string;close: () => void; done: () => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const draftKey=`studyflow_draft_${userId}_${type}`;
  const [draft]=useState<Record<string,string>>(()=>{try{return JSON.parse(localStorage.getItem(draftKey)||"{}") as Record<string,string>}catch{return {}}});
  function saveDraft(event:React.FormEvent<HTMLFormElement>){const target=event.target as HTMLInputElement|HTMLTextAreaElement;if(!target.name||target.type==="password")return;let current:Record<string,string>={};try{current=JSON.parse(localStorage.getItem(draftKey)||"{}") as Record<string,string>}catch{}localStorage.setItem(draftKey,JSON.stringify({...current,[target.name]:target.value}))}
  const initialTopic=initialTask?topics.find(topic=>topic.topic_uid===initialTask.topic_uid):undefined;const [sessionSubject, setSessionSubject] = useState(initialTopic?.subject_uid??subjects[0]?.subject_uid ?? ""); const [sessionTopic, setSessionTopic] = useState(initialTopic?.topic_uid??"");
  const [taskFormSubject,setTaskFormSubject]=useState(topics[0]?.subject_uid??subjects[0]?.subject_uid??"");
  const title = { subject: t("New subject"), topic: t("New topic"), task: t("New task"), session: t("Save session") }[type];
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setBusy(true); setError(""); const f = new FormData(e.currentTarget);
    try {
      if (type === "subject") await api.addSubject({ name: String(f.get("name")), exam_date: String(f.get("date")) || null,color:String(f.get("color")),tags:String(f.get("tags")).split(",").map(value=>value.trim()).filter(Boolean) });
      if (type === "topic") await api.addTopic({ name: String(f.get("name")), subject_uid: String(f.get("subject")), difficulty: String(f.get("difficulty")) });
      if (type === "task") await api.addTask({ title: String(f.get("name")), topic_uid: String(f.get("topic")), deadline: String(f.get("deadline")) ? new Date(String(f.get("deadline"))).toISOString() : null, priority: String(f.get("priority")), notes: String(f.get("notes")) || null });
      if (type === "session") await api.addSession({ title: String(f.get("title")), subject_uid: String(f.get("subject")), topic_uid: String(f.get("topic")) || null, task_uid: String(f.get("task")) || null, duration_minutes: Number(f.get("minutes")), notes: String(f.get("notes")) || null });
      localStorage.removeItem(draftKey);done();
    } catch (err) { setError(err instanceof Error ? err.message : t("Failed to save.")); } finally { setBusy(false); }
  }
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal" onSubmit={submit} onInput={saveDraft} onMouseDown={e => e.stopPropagation()}><button className="icon close" type="button" onClick={close}><X /></button><span className="kicker">{t("Add to StudyFlow")}</span><h2>{title}</h2>
    {(type === "subject" || type === "topic" || type === "task") && <label>{t("Name")}<input name="name" required autoFocus defaultValue={draft.name||""} placeholder={type === "subject" ? t("e.g. Mathematics") : type === "topic" ? t("e.g. Derivatives") : t("What needs to be done?")} /></label>}
    {type === "topic" && <label>{t("Subject")}<SelectField name="subject" required options={subjects.map(s=>({value:s.subject_uid,label:s.name}))}/></label>}
    {type === "session" && <label>{t("Subject")}<SelectField name="subject" required defaultValue={sessionSubject} options={subjects.map(s=>({value:s.subject_uid,label:s.name}))} onChange={value=>{setSessionSubject(value);setSessionTopic("");}}/></label>}
    {type === "subject" && <><label>{t("Exam date")}<DatePicker name="date" defaultValue={draft.date}/><small className="field-hint">{t("Optional — helps set priorities.")}</small></label><SubjectColorField initial={draft.color||"#c8f05a"}/><label>{t("Tags")}<span className="optional">{t("separate with commas")}</span><input name="tags" defaultValue={draft.tags||""} maxLength={300} placeholder={t("e.g. semester 1, exam")}/></label></>}
    {type === "topic" && <label>{t("Difficulty level")}<SelectField name="difficulty" options={[{value:"Łatwy",label:t("Easy")},{value:"Średni",label:t("Medium")},{value:"Trudny",label:t("Hard")}]}/></label>}
    {type === "task" && <><label>{t("Subject")}<SelectField name="task-subject" required defaultValue={taskFormSubject} options={subjects.map(subject=>({value:subject.subject_uid,label:subject.name}))} onChange={setTaskFormSubject}/></label><label>{t("Topic")}<SelectField key={taskFormSubject} name="topic" required options={topics.filter(topic=>topic.subject_uid===taskFormSubject).map(topic=>({value:topic.topic_uid,label:topic.name}))}/><small className="field-hint">{t("The list only contains topics from the selected subject.")}</small></label><div className="field-row"><label>{t("Deadline")}<DatePicker name="deadline" withTime defaultValue={draft.deadline||initialDeadline}/></label><label>{t("Priority")}<SelectField name="priority" defaultValue="MEDIUM" options={[{value:"LOW",label:t("Low")},{value:"MEDIUM",label:t("Medium")},{value:"HIGH",label:t("High")}]}/></label></div><label>{t("Notes")}<textarea name="notes" defaultValue={draft.notes||""} placeholder={t("Materials, scope or a brief tip...")} /></label></>}
    {type === "session" && <><label>{t("Topic")}<span className="optional">{t("optional")}</span><SelectField key={sessionSubject} name="topic" defaultValue={sessionTopic} options={[{value:"",label:t("No specific topic")},...topics.filter(t=>t.subject_uid===sessionSubject).map(t=>({value:t.topic_uid,label:t.name}))]} onChange={setSessionTopic}/></label><label>{t("Task")}<span className="optional">{t("optional")}</span><SelectField key={sessionTopic} name="task" defaultValue={initialTask?.task_uid??""} options={[{value:"",label:t("No specific task")},...tasks.filter(t=>t.topic_uid===sessionTopic).map(t=>({value:t.task_uid,label:t.title}))]}/></label><label>{t("Time in minutes")}<input name="minutes" type="text" inputMode="numeric" pattern="[1-9][0-9]*" required defaultValue="45" /></label><SessionAiFields/></>}
    {error && <p className="form-error">{error}</p>}<button className="primary wide" disabled={busy || ((type === "topic" || type === "session") && !subjects.length) || (type === "task" && !topics.length)}>{busy ? <span className="loader" /> : t("Save")}</button>
  </form></div>;
}

function EditForm({ target, subjects, topics, close, done }: { target: EditTarget; subjects: Subject[]; topics: Topic[]; close: () => void; done: () => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const editedTask=target.kind==="task"?target.value:null;const editedTaskTopic=editedTask?topics.find(topic=>topic.topic_uid===editedTask.topic_uid):undefined;const [taskFormSubject,setTaskFormSubject]=useState(editedTaskTopic?.subject_uid??subjects[0]?.subject_uid??"");
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); setBusy(true); setError(""); const f = new FormData(e.currentTarget);
    try {
      if (target.kind === "subject") await api.updateSubject(target.value.subject_uid, { name: String(f.get("name")), exam_date: String(f.get("date")) || null,color:String(f.get("color")),tags:String(f.get("tags")).split(",").map(value=>value.trim()).filter(Boolean) });
      if (target.kind === "topic") await api.updateTopic(target.value.topic_uid, { name: String(f.get("name")), subject_uid: String(f.get("subject")), difficulty: String(f.get("difficulty")), is_done: f.get("done") === "on" });
      if (target.kind === "task") await api.updateTask(target.value.task_uid, { title: String(f.get("name")), topic_uid: String(f.get("topic")), deadline: String(f.get("deadline")) ? new Date(String(f.get("deadline"))).toISOString() : null, priority: String(f.get("priority")) as Task["priority"], notes: String(f.get("notes")) || null });
      done();
    } catch (err) { setError(err instanceof Error ? err.message : t("Failed to save changes.")); } finally { setBusy(false); }
  }
  const subject = target.kind === "subject" ? target.value : null;
  const topic = target.kind === "topic" ? target.value : null;
  const task = target.kind === "task" ? target.value : null;
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal" onSubmit={submit} onMouseDown={e => e.stopPropagation()}><button className="icon close" type="button" onClick={close}><X /></button><span className="kicker">{t("EDIT")}</span><h2>{target.kind === "subject" ? t("Edit subject") : target.kind === "topic" ? t("Edit topic") : t("Edit task")}</h2>
    <label>{t("Name")}<input name="name" required autoFocus defaultValue={task?.title ?? topic?.name ?? subject?.name} /></label>
    {subject && <><label>{t("Exam date")}<DatePicker name="date" defaultValue={subject.exam_date ?? ""}/><small className="field-hint">{t("Click the field and select a day from the calendar.")}</small></label><SubjectColorField initial={subject.color}/><label>{t("Tags")}<span className="optional">{t("separate with commas")}</span><input name="tags" defaultValue={subject.tags.join(", ")} maxLength={300}/></label></>}
    {topic && <><label>{t("Subject")}<SelectField name="subject" defaultValue={topic.subject_uid} options={subjects.map(s=>({value:s.subject_uid,label:s.name}))}/></label><label>{t("Difficulty level")}<SelectField name="difficulty" defaultValue={difficultyKey(topic.difficulty)??""} options={[{value:"",label:t("No level")},{value:"Łatwy",label:t("Easy")},{value:"Średni",label:t("Medium")},{value:"Trudny",label:t("Hard")}]}/></label><label className="toggle-line"><input name="done" type="checkbox" defaultChecked={topic.is_done} /> {t("Topic completed")}</label></>}
    {task && <><label>{t("Subject")}<SelectField name="task-subject" defaultValue={taskFormSubject} options={subjects.map(item=>({value:item.subject_uid,label:item.name}))} onChange={setTaskFormSubject}/></label><label>{t("Topic")}<SelectField key={taskFormSubject} name="topic" defaultValue={topics.some(topicItem=>topicItem.topic_uid===task.topic_uid&&topicItem.subject_uid===taskFormSubject)?task.topic_uid:undefined} options={topics.filter(topicItem=>topicItem.subject_uid===taskFormSubject).map(topicItem=>({value:topicItem.topic_uid,label:topicItem.name}))}/><small className="field-hint">{t("After changing the subject, select a topic belonging to it.")}</small></label><div className="field-row"><label>{t("Deadline")}<DatePicker name="deadline" withTime defaultValue={task.deadline??""}/></label><label>{t("Priority")}<SelectField name="priority" defaultValue={task.priority} options={[{value:"LOW",label:t("Low")},{value:"MEDIUM",label:t("Medium")},{value:"HIGH",label:t("High")}]}/></label></div><label>{t("Notes")}<textarea name="notes" defaultValue={task.notes??""} placeholder={t("Materials, scope or tips...")} /></label></>}
    {error && <p className="form-error">{error}</p>}<button className="primary wide" disabled={busy}>{busy ? <span className="loader" /> : t("Save changes")}</button>
  </form></div>;
}

function ProfileForm({ user, avatar, changeAvatar, close, done, logout }: { user: User; avatar:string|null; changeAvatar:(value:string|null)=>void; close:()=>void; done:()=>void; logout:()=>void }) {
  const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [preview,setPreview]=useState(avatar);
  function selectAvatar(file?:File){if(!file)return;if(!file.type.startsWith("image/")){setError(t("Select an image file."));return}if(file.size>2_000_000){setError(t("The photo can be a maximum of 2 MB."));return}const reader=new FileReader();reader.onload=()=>{setPreview(String(reader.result));setError("")};reader.readAsDataURL(file)}
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setError("");const data=new FormData(event.currentTarget);const password=String(data.get("password"));if(password&&password!==String(data.get("confirm_password"))){setError(t("Passwords must match."));return}setBusy(true);try{await api.updateMe({username:String(data.get("username")),email:String(data.get("email"))||null,...(password?{password}:{})});changeAvatar(preview);done()}catch(err){setError(err instanceof Error?err.message:t("Failed to save account."))}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal profile-modal" onSubmit={submit} onMouseDown={event=>event.stopPropagation()}><button className="icon close" type="button" onClick={close}><X/></button><span className="kicker">{t("YOUR ACCOUNT")}</span><h2>{t("Account details")}</h2><div className="avatar-editor"><span>{preview?<img src={preview} alt={t("Profile picture preview")}/>:initials(user.username)}</span><label><ImagePlus/>{t("Upload photo")}<input type="file" accept="image/*" onChange={event=>selectAvatar(event.target.files?.[0])}/></label>{preview&&<button type="button" onClick={()=>setPreview(null)}>{t("Delete")}</button>}</div>
    <label>{t("Username")}<input name="username" minLength={2} required defaultValue={user.username}/></label><label>{t("E-mail address")}<input name="email" type="email" defaultValue={user.email??""}/></label><label>{t("New password")}<span className="optional">{t("leave blank to keep unchanged")}</span><input name="password" type="password" minLength={8} placeholder={t("Minimum 8 characters")} autoComplete="new-password"/></label><label>{t("Confirm new password")}<input name="confirm_password" type="password" minLength={8} placeholder={t("Enter new password again")} autoComplete="new-password"/></label>{error&&<p className="form-error">{error}</p>}<button className="primary wide" disabled={busy}>{busy?<span className="loader"/>:t("Save account")}</button><button className="logout-action" type="button" onClick={logout}><LogOut/>{t("Log out")}</button></form></div>
}

function PreferencesForm({user,close,done}:{user:User;close:()=>void;done:()=>void}){
  const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [minutes,setMinutes]=useState(String(user.preferred_minutes));const [shortcut,setShortcut]=useState(user.task_shortcut);const [aiShortcut,setAiShortcut]=useState(user.ai_shortcut);
  function captureShortcut(event:React.KeyboardEvent<HTMLInputElement>,kind:"task"|"ai"){
    if(event.key==="Tab")return;
    event.preventDefault();
    const value=shortcutFromKey(event);
    if(value===null)return;
    if(shortcutsConflict(value,kind==="task"?aiShortcut:shortcut)){setError(t("This combination is already assigned to another shortcut. Please choose a different one."));return}
    setError("");
    if(kind==="task")setShortcut(value);else setAiShortcut(value);
  }
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const amount=Number(minutes);if(!Number.isInteger(amount)||amount<10||amount>240){setError(t("Enter a time from 10 to 240 minutes."));return}if(shortcutsConflict(shortcut,aiShortcut)){setError(t("Task and AI Assistant shortcuts must be different."));return}setBusy(true);setError("");try{await api.updateMe({timezone:String(new FormData(event.currentTarget).get("timezone")),preferred_minutes:amount,task_shortcut:shortcut,ai_shortcut:aiShortcut});done()}catch(err){setError(err instanceof Error?err.message:t("Failed to save settings."))}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal profile-modal" onSubmit={submit} onMouseDown={event=>event.stopPropagation()}><button className="icon close" type="button" onClick={close}><X/></button><span className="kicker">{t("USER SETTINGS")}</span><h2>{t("Study and shortcuts")}</h2><TimezoneField value={user.timezone}/><label>{t("Suggested daily study time")}<input name="minutes" type="text" inputMode="numeric" pattern="[0-9]+" value={minutes} onChange={event=>setMinutes(event.target.value.replace(/\D/g,""))} placeholder={t("e.g. 45")}/><small className="field-hint">{t("This is a starting point for AI. You can customize each day of the plan later.")}</small></label><label>{t("Task addition shortcut")}<input value={shortcut} readOnly onKeyDown={event=>captureShortcut(event,"task")} placeholder={t("Click and press the combination")}/><small className="field-hint">{t("On Mac, you can use ⌘ or Option. Backspace disables the shortcut.")}</small></label><label>{t("AI Assistant shortcut (T3ACH)")}<input value={aiShortcut} readOnly onKeyDown={event=>captureShortcut(event,"ai")} placeholder={t("Click and press the combination")}/><small className="field-hint">{t("Backspace disables the shortcut. Use a different combination than for the task.")}</small></label>{error&&<p className="form-error">{error}</p>}<button className="primary wide" disabled={busy}>{busy?<span className="loader"/>:t("Save settings")}</button></form></div>
}

function SessionEditForm({session,subjects,topics,tasks,close,done}:{session:Session;subjects:Subject[];topics:Topic[];tasks:Task[];close:()=>void;done:()=>void}) {
  const [subject,setSubject]=useState(session.subject_uid); const [topic,setTopic]=useState(session.topic_uid??""); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget);try{await api.updateSession(session.study_uid,{title:String(f.get("title")),subject_uid:String(f.get("subject")),topic_uid:String(f.get("topic"))||null,task_uid:String(f.get("task"))||null,duration_minutes:Number(f.get("minutes")),notes:String(f.get("notes"))||null});done()}catch(err){setError(err instanceof Error?err.message:t("Failed to save session"))}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={close}><form className="modal session-detail" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><button className="icon close" type="button" onClick={close}><X/></button><span className="kicker">{new Intl.DateTimeFormat(locale(),{dateStyle:"long",timeStyle:"short"}).format(new Date(session.started_at))}</span><h2>{t("Session details")}</h2><label>{t("Subject")}<SelectField name="subject" defaultValue={subject} options={subjects.map(s=>({value:s.subject_uid,label:s.name}))} onChange={v=>{setSubject(v);setTopic("")}}/></label><label>{t("Topic")}<SelectField name={`session-topic-${subject}`} defaultValue={topic} options={[{value:"",label:t("No specific topic")},...topics.filter(t=>t.subject_uid===subject).map(t=>({value:t.topic_uid,label:t.name}))]} onChange={setTopic}/></label><label>{t("Task")}<SelectField name={`session-task-${topic}`} defaultValue={session.task_uid??""} options={[{value:"",label:t("No specific task")},...tasks.filter(t=>t.topic_uid===topic).map(t=>({value:t.task_uid,label:t.title}))]}/></label><label>{t("Study time in minutes")}<input name="minutes" type="text" inputMode="numeric" pattern="[1-9][0-9]*" required defaultValue={session.duration_minutes??1}/></label><SessionAiFields initialTitle={session.title} initialNotes={session.notes??""}/>{error&&<p className="form-error">{error}</p>}<button className="primary wide" disabled={busy}>{busy?<span className="loader"/>:t("Save changes")}</button></form></div>
}

