  useEffect(()=>{if(view!=="subjects"||!subjects.length)return;const frame=requestAnimationFrame(()=>{document.querySelectorAll<HTMLElement>(".subject-grid .subject-card").forEach((card,index)=>{const subject=subjects[index];if(!subject)return;card.tabIndex=0;card.setAttribute("role","button");card.setAttribute("aria-label",t("Open subjects of {0}", subject.name));card.onclick=event=>{if((event.target as HTMLElement).closest("button"))return;setTopicScope(subject.subject_uid);setFocusedTopic(null);setView("topics")};card.onkeydown=event=>{if((event.key==="Enter"||event.key===" ")&&!(event.target as HTMLElement).closest("button")){event.preventDefault();setTopicScope(subject.subject_uid);setFocusedTopic(null);setView("topics")}}})});return()=>{cancelAnimationFrame(frame);document.querySelectorAll<HTMLElement>(".subject-grid .subject-card").forEach(card=>{card.onclick=null;card.onkeydown=null})}},[view,subjects]);
